window.__PAGE_RUNTIME_PARTIALS__["partials/guia-redes11-rap02-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA · FPI\u003c/div\u003e\n      \u003ch2 data-no-guide-remap\u003eGuía 10 - Comprobar la conectividad de la red\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinformáticos · Redes (RAP 02) · Grado 11\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha u-hidden\" id=\"sb-ficha-ok\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda en este navegador y en la nube.\u003c/p\u003e\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eInformación\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificación\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentación\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eActividades\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128172;\u003c/span\u003e 3.1 Reflexión Inicial \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128269;\u003c/span\u003e 3.2 Contextualización \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128218;\u003c/span\u003e 3.3 Apropiación \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128640;\u003c/span\u003e 3.4 Transferencia \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#control-avance\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#9989;\u003c/span\u003e Control de avance\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128202;\u003c/span\u003e Evidencias\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128279;\u003c/span\u003e Referencias\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\" data-no-guide-remap\u003e\n      \u003cdiv class=\"nav-label\"\u003eGuía asignada\u003c/div\u003e\n      \u003ca class=\"nav-guide current\" href=\"#\" data-current-file=\"runtime-wrapper.html\"\u003e\n        \u003cspan class=\"g-icon\"\u003e\u0026#128215;\u003c/span\u003e\n        \u003cspan class=\"g-info\"\u003e\n          \u003cspan class=\"g-num\"\u003eGuía 10\u003c/span\u003e\n          \u003cspan class=\"g-name\"\u003eRedes RAP02\u003c/span\u003e\n        \u003c/span\u003e\n        \u003cspan class=\"g-tag actual\"\u003eActual\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cdiv class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\" data-no-guide-remap\u003e\u003cstrong\u003eGuía 10 - Comprobar la conectividad de la red\u003c/strong\u003e\u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan data-ctx-duracion-corta\u003e40 horas\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eSanta Bárbara\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\" data-redes11-guide=\"guia-redes11-rap02\"\u003e\n\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\" data-no-guide-remap\u003eGuía 10 | Fase: \u003cspan data-ctx-fase\u003eAnálisis\u003c/span\u003e · RAP 02 · Grado 11\u003c/div\u003e\n        \u003ch1\u003eComprobar la conectividad de la red\u003c/h1\u003e\n        \u003cp\u003eRedes LAN y WAN, subneteo FLSM, herramientas de validación (ipconfig, ping, tracert, nslookup) y configuración y prueba de\n        dos subredes en Cisco Packet Tracer para la papelería de la señora Carmen.\u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; I.E. Santa Bárbara · 11A / 11B\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#9201; \u003cspan data-ctx-duracion-corta\u003e40 horas\u003c/span\u003e\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; Código: 233108 V1\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"control-avance\" class=\"section-title\"\u003eTu control de avance\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-green\"\u003e\u0026#9989;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003e\u0026iquest;Qu\u0026eacute; llevas y qu\u0026eacute; te falta?\u003c/h3\u003e\u003cp\u003eSe actualiza solo con tus entregas y respuestas guardadas\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv data-act-std-avance\u003e\u003cp class=\"intro-text\"\u003eCargando tu avance...\u003c/p\u003e\u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n            \u003cp\u003eEsta tabla se marca sola: \u003cstrong\u003eEntregada\u003c/strong\u003e cuando subes la evidencia a Drive y\n            \u003cstrong\u003eGuardada\u003c/strong\u003e cuando guardas tus respuestas. Lo que siga en Pendiente es lo que te falta.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificación de la Guía\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-green\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eDatos del Programa de Formación\u003c/h3\u003e\u003cp\u003eInformación oficial del programa y la competencia\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\u003ctable class=\"data-table ident-table\"\u003e\u003ctbody\u003e\u003ctr\u003e\u003ctd\u003eDenominación del Programa\u003c/td\u003e\u003ctd\u003eTécnico en Sistemas Teleinformáticos.\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eCódigo del Programa\u003c/td\u003e\u003ctd\u003e233108 V1\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eNombre del Proyecto Formativo\u003c/td\u003e\u003ctd\u003eFortalecimiento de los Servicios Teleinformáticos de Equipos y Redes en las MiPymes de la Región de Boyacá.\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eFase del Proyecto\u003c/td\u003e\u003ctd\u003e\u003cspan data-ctx-fase\u003eAnálisis\u003c/span\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eActividad del Proyecto\u003c/td\u003e\u003ctd\u003eDiagnosticar el estado de la infraestructura de redes y equipos informáticos y solicitudes de servicio técnico presente en el entorno de trabajo.\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eCompetencia\u003c/td\u003e\u003ctd\u003e\u003cspan data-ctx-competencia\u003e280102129 — Evaluar red de acuerdo con procedimientos de telecomunicaciones y normativa técnica.\u003c/span\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eResultado de Aprendizaje\u003c/td\u003e\u003ctd\u003e\u003cspan data-ctx-rap\u003eRAP 02 — Comprobar la conectividad de la red, de acuerdo con normativa de telecomunicaciones y orden de trabajo.\u003c/span\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eDuración\u003c/td\u003e\u003ctd\u003e\u003cspan data-ctx-duracion\u003e40 horas\u003c/span\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/tbody\u003e\u003c/table\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentación\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eEmpieza por aquí:\u003c/strong\u003e conoce de qué trata la guía y qué vas a lograr.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e🧭 ¿Cómo trabajar esta guía? Paso a paso\u003c/div\u003e\n        \u003col\u003e\n          \u003cli\u003e\u003cstrong\u003eLee cada bloque y sus recursos\u003c/strong\u003e antes de responder.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eResuelve cada actividad\u003c/strong\u003e en orden y escribe tus respuestas en los campos de la guía.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eGuarda tus respuestas\u003c/strong\u003e con el botón de cada actividad (al guardar, la actividad queda enviada).\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEntrega las evidencias\u003c/strong\u003e que lo pidan con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eRevisa \"Tu control de avance\"\u003c/strong\u003e: te muestra qué llevas Entregado, Guardado y Pendiente.\u003c/li\u003e\n        \u003c/ol\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-blue\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eBienvenida a la Guía\u003c/h3\u003e\u003cp\u003eDe dividir una red a comprobar que funciona\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003eCordial saludo, aprendiz.\u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003eEn el RAP 01 usted aprendió a clasificar los tipos de redes, identificar topologías y aplicar el\n          direccionamiento IP básico. La señora Carmen, dueña de la papelería que usted ayudó a conectar, ahora enfrenta un nuevo\n          reto: abrió una sala de atención al público independiente de su oficina administrativa y quiere que cada zona tenga su\n          propia red interna, sin perder la posibilidad de comunicarse entre ellas cuando sea necesario. Ese es exactamente el\n          problema que resuelve la creación de \u003cstrong\u003esubredes\u003c/strong\u003e.\u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003eEn esta guía usted desarrollará el RAP 02: comprobará la conectividad de una red aplicando conceptos de\n          redes LAN y WAN, dividirá una red en subredes mediante cálculos de direccionamiento IP, y utilizará herramientas de\n          validación como \u003ccode\u003eipconfig\u003c/code\u003e, \u003ccode\u003eping\u003c/code\u003e, \u003ccode\u003etracert\u003c/code\u003e y \u003ccode\u003enslookup\u003c/code\u003e para verificar que\n          la red diseñada funciona correctamente. El resultado será la configuración y prueba de \u003cstrong\u003edos subredes en Cisco\n          Packet Tracer\u003c/strong\u003e.\u003c/p\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"reflexion\" class=\"section-title\"\u003e3.1 Actividades de reflexión inicial\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 Aquí no se evalúa el acierto, sino su participación: responda con confianza.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-orange\"\u003e\u0026#128172;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eLa papelería de la señora Carmen creció\u003c/h3\u003e\u003cp\u003eReflexión individual escrita + socialización\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \n          \u003cdiv class=\"activity open mission-card r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eReflexión individual escrita y socialización\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eActivar conocimientos previos sobre la organización y división de redes (máx. 30 min).\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003e5 respuestas escritas + definición grupal de subred.\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128221; Situación para reflexionar\u003c/div\u003e\u003cp\u003eLa papelería de la señora Carmen creció. Ahora tiene un área de ventas al público (caja y 2 puntos de atención) y un área administrativa (gerencia, contabilidad y bodega), en espacios separados del mismo local. Ella le pide: \u003cem\u003e“Necesito que cada área tenga su propia red, para que si algo falla en ventas no afecte a administración, pero que desde mi oficina pueda seguir viendo los equipos de ambas partes.”\u003c/em\u003e\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e activar los conocimientos previos sobre la organización y división de redes (máximo 30 minutos). \u003cstrong\u003ePaso 1:\u003c/strong\u003e responda con sus propias palabras. No busque información aún: escriba lo que ya sabe o intuye a partir de lo aprendido en el RAP 01.\u003c/p\u003e\u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Por qué separar la red de ventas y la red administrativa podría mejorar la organización y la seguridad de la papelería?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g11c_311_p1\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Qué problemas podría tener la señora Carmen si mantiene los 6 equipos (3 de ventas y 3 administrativos) en una sola red sin dividir?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g11c_311_p2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. ¿Ha escuchado el término “subred” o “subnetting”? ¿Qué cree que significa dividir una red en subredes?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g11c_311_p3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e4. Si tuviera que repartir 254 direcciones disponibles en una red entre 2 grupos de igual tamaño, ¿cómo lo haría? Relacione su respuesta con la idea de dividir una red.\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g11c_311_p4\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e5. ¿Qué comando aprendió en el RAP 01 (o conoce) que permite ver la configuración IP de un equipo? ¿Para qué le serviría ahora?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g11c_311_p5\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128483; Paso 2 — Socialización\u003c/div\u003e\u003cp\u003eEl instructor modera una conversación abierta. Cada aprendiz comparte brevemente una respuesta (2–3 minutos) y entre todos se construye una primera definición grupal de “subred”.\u003c/p\u003e\u003c/div\u003e\n                \u003clabel\u003e\u003cspan\u003eDefinición grupal de “subred” construida en la socialización\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_311_socializacion\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"c11Reflexion311DeadlineControls\" class=\"u-mt-16\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group r11-actions\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarc11Reflexion311\" class=\"btn-save-response\" onclick=\"actStd_save_c11Reflexion311()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_c11Reflexion311()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusc11Reflexion311\" class=\"activity-saved-notice u-saved\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n                \u003cdiv id=\"c11Reflexion311GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"contexto\" class=\"section-title\"\u003e3.2 Contextualización e identificación de conocimientos\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003ePropósito:\u003c/strong\u003e construir la base conceptual sobre redes LAN, redes WAN, fundamentos del subneteo y herramientas de validación de conectividad, necesaria para diseñar y comprobar subredes.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-purple\"\u003e\u0026#128269;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eExploración visual por bloques temáticos\u003c/h3\u003e\u003cp\u003e4 bloques · mapa mental integrador · revisión entre pares\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003ePara cada bloque encontrará un video y un recurso de apoyo. Primero observe el recurso completo, luego responda las preguntas y elabore el producto individual solicitado.\u003c/p\u003e\n          \u003cdiv class=\"activity open r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eBloque A — Redes LAN\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eReconocer qué hace que una red sea LAN.\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003eFicha técnica de una LAN.\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127909; Video de referencia\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eRedes LAN: características, diseño y equipos de conectividad — explicación visual\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u0026#128736; Recurso adicional: \u003ca href=\"https://skillsforall.com/course/networking-basics\" target=\"_blank\" rel=\"noopener\"\u003eCisco Skills for All — Networking Basics, Módulo 2\u003c/a\u003e\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eMientras observa, responda:\u003c/strong\u003e\u003c/p\u003e\u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Qué características debe tener la red de ventas de la papelería para considerarse una LAN?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_321_q1\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Qué equipos de conectividad (switch, access point) necesitaría esa red?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_321_q2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. ¿Qué estándar rige el cableado y la velocidad de una LAN típica?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_321_q3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128221; Producto individual — Ficha técnica de una LAN\u003c/div\u003e\u003cp\u003eDescriba: alcance, velocidad típica, equipos requeridos y un ejemplo aplicado a la papelería.\u003c/p\u003e\u003c/div\u003e\n                \u003clabel\u003e\u003cspan\u003eFicha técnica — Alcance\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_321_ficha_alcance\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eFicha técnica — Velocidad típica\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_321_ficha_velocidad\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eFicha técnica — Equipos requeridos\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_321_ficha_equipos\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eFicha técnica — Ejemplo aplicado a la papelería\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_321_ficha_ejemplo\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"c11LanA321DeadlineControls\" class=\"u-mt-16\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group r11-actions\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarc11LanA321\" class=\"btn-save-response\" onclick=\"actStd_save_c11LanA321()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_c11LanA321()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusc11LanA321\" class=\"activity-saved-notice u-saved\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n                \u003cdiv id=\"c11LanA321GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"activity open r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.2\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eBloque B — Redes WAN\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eDiferenciar la LAN de la WAN y ubicar el equipo frontera.\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003eEsquema LAN – router – WAN.\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127909; Video de referencia\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eRedes WAN: características, protocolos y equipos de conectividad — explicación visual\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u0026#128736; Recurso adicional: \u003ca href=\"https://skillsforall.com/course/networking-basics\" target=\"_blank\" rel=\"noopener\"\u003eCisco Skills for All — Networking Basics, Módulo 3\u003c/a\u003e\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eMientras observa, responda:\u003c/strong\u003e\u003c/p\u003e\u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Cómo se conecta la red de la papelería con Internet? ¿Qué tipo de red es esa conexión?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_322_q1\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Qué diferencia hay entre la LAN de la papelería y la WAN que la conecta con su proveedor de Internet?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_322_q2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. ¿Qué equipo actúa como frontera entre la LAN y la WAN?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_322_q3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128221; Producto individual — Esquema LAN–router–WAN\u003c/div\u003e\u003cp\u003eElabore un esquema simple que muestre la LAN de la papelería conectada a través de un router a la WAN (Internet). Dibújelo a mano o en una herramienta digital e inclúyalo en el PDF de exploración contextual (actividad 3.2.5). Aquí describa brevemente su esquema.\u003c/p\u003e\u003c/div\u003e\n                \u003clabel\u003e\u003cspan\u003eDescripción de su esquema (equipos, conexiones y por dónde sale a Internet)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_322_esquema\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"c11WanB322DeadlineControls\" class=\"u-mt-16\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group r11-actions\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarc11WanB322\" class=\"btn-save-response\" onclick=\"actStd_save_c11WanB322()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_c11WanB322()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusc11WanB322\" class=\"activity-saved-notice u-saved\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n                \u003cdiv id=\"c11WanB322GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"activity open r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.3\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eBloque C — Fundamentos del subneteo\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eComprender por qué y cómo se divide una red.\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003eExplicación de subred (máx. 5 líneas).\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127909; Video de referencia\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eSubnetting explicado paso a paso: por qué y cómo dividir una red\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u0026#128736; Recurso adicional: \u003ca href=\"https://www.rfc-editor.org/rfc/rfc950\" target=\"_blank\" rel=\"noopener\"\u003eRFC 950 — Internet Standard Subnetting Procedure\u003c/a\u003e\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eMientras observa, responda:\u003c/strong\u003e\u003c/p\u003e\u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Qué cambia en la máscara de subred cuando se “pide prestado” un bit de host?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_323_q1\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Por qué la primera y la última dirección de cada subred no se pueden asignar a un equipo?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_323_q2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. Si divide una red /24 en 2 partes iguales, ¿qué nueva máscara resulta?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_323_q3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128221; Producto individual\u003c/div\u003e\u003cp\u003eExplique con sus palabras, en máximo 5 líneas, qué es una subred y por qué la papelería la necesita.\u003c/p\u003e\u003c/div\u003e\n                \u003clabel\u003e\u003cspan\u003eQué es una subred y por qué la papelería la necesita (máximo 5 líneas)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_323_explicacion\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"c11SubnetC323DeadlineControls\" class=\"u-mt-16\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group r11-actions\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarc11SubnetC323\" class=\"btn-save-response\" onclick=\"actStd_save_c11SubnetC323()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_c11SubnetC323()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusc11SubnetC323\" class=\"activity-saved-notice u-saved\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n                \u003cdiv id=\"c11SubnetC323GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"activity open r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.4\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eBloque D — Herramientas de validación de conectividad\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eUsar ipconfig, ping, tracert y nslookup para validar conectividad.\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003eCaptura de ipconfig /all con IP, máscara y gateway.\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127909; Video de referencia\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eComandos de red en Windows: ipconfig, ping, tracert y nslookup\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u0026#128736; Recurso adicional: \u003ca href=\"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig\" target=\"_blank\" rel=\"noopener\"\u003eMicrosoft Learn — Windows Commands (ipconfig, ping, tracert, nslookup)\u003c/a\u003e\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eMientras observa, responda:\u003c/strong\u003e\u003c/p\u003e\u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. ¿Qué comando usaría para confirmar en qué subred quedó configurado un equipo?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_324_q1\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. ¿Qué diferencia hay entre lo que muestra ping y lo que muestra tracert?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_324_q2\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. ¿Para qué serviría nslookup si un equipo de la papelería no puede abrir una página web?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_324_q3\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128221; Producto individual — \u003ccode\u003eipconfig /all\u003c/code\u003e\u003c/div\u003e\u003cp\u003eEjecute \u003ccode\u003eipconfig /all\u003c/code\u003e en su propio equipo (Windows + R → \u003ccode\u003ecmd\u003c/code\u003e), capture el resultado (Windows + Shift + S) e identifique dirección IP, máscara y gateway. La captura va en el PDF de exploración contextual (3.2.5).\u003c/p\u003e\u003c/div\u003e\n                \u003clabel\u003e\u003cspan\u003eDirección IP de su equipo\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_324_ip\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003eMáscara de subred\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_324_mascara\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003ePuerta de enlace predeterminada (gateway)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_324_gateway\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"c11HerramD324DeadlineControls\" class=\"u-mt-16\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group r11-actions\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarc11HerramD324\" class=\"btn-save-response\" onclick=\"actStd_save_c11HerramD324()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_c11HerramD324()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusc11HerramD324\" class=\"activity-saved-notice u-saved\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n                \u003cdiv id=\"c11HerramD324GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"activity open mission-card r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.5\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eEntrega — Exploración contextual (Bloques A–D, PDF)\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eCompilar los 4 productos de los bloques A–D.\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003eExploracion_Contextual_NombreAprendiz_FICHA.pdf\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003eCompile en un solo PDF los 4 productos individuales de los Bloques A–D (ficha técnica de la LAN, esquema LAN–router–WAN, explicación de subred y captura de \u003ccode\u003eipconfig /all\u003c/code\u003e con IP, máscara y gateway identificados) y entréguelo a Drive.\u003c/p\u003e\n              \u003csection class=\"r11-evidence\" aria-label=\"Entrega de evidencia 3.2.5\" data-r11-formats=\".pdf\"\u003e\n                \u003cdiv class=\"r11-evidence__head\"\u003e\u003cspan class=\"r11-evidence__icon\" aria-hidden=\"true\"\u003e\u0026#128230;\u003c/span\u003e\n                  \u003cdiv\u003e\u003cstrong\u003eEntrega de evidencia\u003c/strong\u003e\u003cspan class=\"r11-evidence__title\"\u003eExploracion contextual - Bloques A a D (PDF)\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n                \u003cdl class=\"r11-evidence__facts\"\u003e\n                  \u003cdiv\u003e\u003cdt\u003eArchivo\u003c/dt\u003e\u003cdd\u003e\u003ccode\u003eExploracion_Contextual_NombreAprendiz_FICHA.pdf\u003c/code\u003e\u003c/dd\u003e\u003c/div\u003e\n                  \u003cdiv\u003e\u003cdt\u003eFormatos admitidos\u003c/dt\u003e\u003cdd\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.pdf\u003c/span\u003e\u003c/dd\u003e\u003c/div\u003e\n                \u003c/dl\u003e\n                \u003cp class=\"r11-evidence__help\"\u003eUse \u003cstrong\u003eEntregar por formulario seguro\u003c/strong\u003e: el portal muestra el estado de subida, confirma la entrega con fecha y hora, y si falla le indica el error y le permite reintentar.\u003c/p\u003e\n                \u003cdiv data-act-std-delivery=\"c11Exploracion325\"\u003e\u003c/div\u003e\n              \u003c/section\u003e\n              \u003cdiv id=\"c11Exploracion325GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"activity open mission-card r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.6\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eMapa mental integrador: LAN, WAN y subneteo\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eIntegrar LAN, WAN, subneteo y herramientas en una sola vista.\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003eMapaMental_Redes_NombreAprendiz_FICHA.pdf\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003eDespués de explorar los 4 bloques, construya un mapa mental que integre los conceptos en una sola vista.\u003c/p\u003e\n              \u003cdiv class=\"table-scroll\"\u003e\u003ctable class=\"data-table\"\u003e\u003cthead\u003e\u003ctr\u003e\u003cth\u003eElemento\u003c/th\u003e\u003cth\u003eContenido\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\u003ctbody\u003e\u003ctr\u003e\u003ctd\u003eNodo central\u003c/td\u003e\u003ctd\u003eCOMPROBAR LA CONECTIVIDAD DE LA RED\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eRama 1 — Redes LAN\u003c/td\u003e\u003ctd\u003eCaracterísticas, equipos, ejemplo (papelería — ventas).\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eRama 2 — Redes WAN\u003c/td\u003e\u003ctd\u003eCaracterísticas, ejemplo (conexión a Internet).\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eRama 3 — Subneteo\u003c/td\u003e\u003ctd\u003eMáscara extendida, dirección de red, broadcast, rango de host.\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eRama 4 — Herramientas de validación\u003c/td\u003e\u003ctd\u003eipconfig, ping, tracert, nslookup, con la función de cada una.\u003c/td\u003e\u003c/tr\u003e\u003c/tbody\u003e\u003c/table\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003eEl mapa debe mostrar \u003cstrong\u003eal menos 2 conexiones cruzadas entre ramas\u003c/strong\u003e (ej. subred ↔ LAN ↔ ping).\u003c/p\u003e\n              \u003cdiv class=\"table-scroll\"\u003e\u003ctable class=\"data-table\"\u003e\u003cthead\u003e\u003ctr\u003e\u003cth\u003eHerramienta\u003c/th\u003e\u003cth\u003eTipo\u003c/th\u003e\u003cth\u003eEnlace\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\u003ctbody\u003e\u003ctr\u003e\u003ctd\u003eMindMeister\u003c/td\u003e\u003ctd\u003eEn línea — colaborativo\u003c/td\u003e\u003ctd\u003e\u003ca href=\"https://www.mindmeister.com\" target=\"_blank\" rel=\"noopener\"\u003emindmeister.com\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eCmapTools\u003c/td\u003e\u003ctd\u003eInstalable — offline disponible\u003c/td\u003e\u003ctd\u003e\u003ca href=\"https://cmap.ihmc.us\" target=\"_blank\" rel=\"noopener\"\u003ecmap.ihmc.us\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eCanva — Mapa mental\u003c/td\u003e\u003ctd\u003eEn línea — plantillas visuales\u003c/td\u003e\u003ctd\u003e\u003ca href=\"https://www.canva.com/mind-map\" target=\"_blank\" rel=\"noopener\"\u003ecanva.com/mind-map\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eDraw.io\u003c/td\u003e\u003ctd\u003eEn línea — muy flexible\u003c/td\u003e\u003ctd\u003e\u003ca href=\"https://app.diagrams.net\" target=\"_blank\" rel=\"noopener\"\u003eapp.diagrams.net\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/tbody\u003e\u003c/table\u003e\u003c/div\u003e\n              \u003csection class=\"r11-evidence\" aria-label=\"Entrega de evidencia 3.2.6\" data-r11-formats=\".pdf,.png,.jpg,.jpeg\"\u003e\n                \u003cdiv class=\"r11-evidence__head\"\u003e\u003cspan class=\"r11-evidence__icon\" aria-hidden=\"true\"\u003e\u0026#128230;\u003c/span\u003e\n                  \u003cdiv\u003e\u003cstrong\u003eEntrega de evidencia\u003c/strong\u003e\u003cspan class=\"r11-evidence__title\"\u003eMapa mental integrador: LAN, WAN y subneteo (PDF)\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n                \u003cdl class=\"r11-evidence__facts\"\u003e\n                  \u003cdiv\u003e\u003cdt\u003eArchivo\u003c/dt\u003e\u003cdd\u003e\u003ccode\u003eMapaMental_Redes_NombreAprendiz_FICHA.pdf\u003c/code\u003e\u003c/dd\u003e\u003c/div\u003e\n                  \u003cdiv\u003e\u003cdt\u003eFormatos admitidos\u003c/dt\u003e\u003cdd\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.pdf\u003c/span\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.png\u003c/span\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.jpg\u003c/span\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.jpeg\u003c/span\u003e\u003c/dd\u003e\u003c/div\u003e\n                \u003c/dl\u003e\n                \u003cp class=\"r11-evidence__help\"\u003eUse \u003cstrong\u003eEntregar por formulario seguro\u003c/strong\u003e: el portal muestra el estado de subida, confirma la entrega con fecha y hora, y si falla le indica el error y le permite reintentar.\u003c/p\u003e\n                \u003cdiv data-act-std-delivery=\"c11MapaMental326\"\u003e\u003c/div\u003e\n              \u003c/section\u003e\n              \u003cdiv id=\"c11MapaMental326GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"activity open r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.7\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eSocialización y revisión entre pares\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eContrastar y afinar la comprensión en equipos de 3.\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003eDiferencias, explicación común, conceptos y pregunta técnica.\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003eEn equipos de 3 aprendices comparen sus mapas mentales y productos de exploración. El objetivo NO es hacer una exposición formal, sino contrastar y afinar la comprensión antes de pasar al cálculo de subredes.\u003c/p\u003e\u003carticle class=\"notes-card\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. Comparen sus mapas mentales e identifiquen al menos 2 diferencias significativas. Anótenlas.\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_327_diferencias\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. Entre los 3, acuerden una explicación común de qué es la dirección de red y qué es la dirección de broadcast.\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_327_red_broadcast\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. Identifiquen 2 conceptos que cada integrante no tenía claro e intenten resolverlos entre el equipo antes de consultar al instructor.\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_327_conceptos\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e4. Preparen 1 pregunta técnica genuina que el equipo no pudo resolver solo para plantearla al instructor en la plenaria final.\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g11c_327_pregunta\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"c11Pares327DeadlineControls\" class=\"u-mt-16\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group r11-actions\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarc11Pares327\" class=\"btn-save-response\" onclick=\"actStd_save_c11Pares327()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_c11Pares327()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusc11Pares327\" class=\"activity-saved-notice u-saved\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n                \u003cdiv id=\"c11Pares327GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"apropiacion\" class=\"section-title\"\u003e3.3 Actividades de apropiación\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 Taller de subneteo FLSM de la red de la papelería (192.168.20.0/24).\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-blue\"\u003e\u0026#128218;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eTaller de subneteo — Red de la papelería\u003c/h3\u003e\u003cp\u003e5 ejercicios con procedimiento completo\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \n          \u003cdiv class=\"activity open mission-card r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eTaller de subneteo (Ejercicios 1–5)\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eAplicar FLSM para dividir 192.168.20.0/24 en dos subredes.\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003eTaller_Subneteo_NombreAprendiz_FICHA.pdf (Ejercicios 1–5).\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e aplicar el método de subneteo de longitud fija (FLSM) para dividir una red en dos subredes, calculando correctamente rangos de host, dirección de red y de broadcast.\u003c/p\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128208; Fundamentos del subneteo (FLSM) — procedimiento para dividir una red en 2 subredes iguales\u003c/div\u003e\u003col\u003e\n                \u003cli\u003eDetermine cuántos bits necesita prestar para obtener el número de subredes requerido: con 1 bit prestado se obtienen 2 subredes (2¹ = 2).\u003c/li\u003e\n                \u003cli\u003eSume ese bit a la máscara original: una red /24 (255.255.255.0) pasa a ser /25 (255.255.255.128) en cada subred.\u003c/li\u003e\n                \u003cli\u003eCalcule el “salto” entre subredes: 256 − 128 = 128, es decir, cada subred tiene 128 direcciones.\u003c/li\u003e\n                \u003cli\u003eCada subred inicia en un múltiplo del salto (0, 128, 256…) y termina un número antes del siguiente múltiplo.\u003c/li\u003e\n                \u003cli\u003eLa primera dirección de cada bloque es la dirección de red; la última es la dirección de broadcast; las intermedias son direcciones de host asignables.\u003c/li\u003e\n              \u003c/ol\u003e\n              \u003cp\u003e\u003cstrong\u003eEjemplo guiado: red 192.168.20.0/24 dividida en 2 subredes:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul\u003e\n                \u003cli\u003eSubred 1 (Ventas): 192.168.20.0/25 — Rango de host: 192.168.20.1 a 192.168.20.126 — Broadcast: 192.168.20.127\u003c/li\u003e\n                \u003cli\u003eSubred 2 (Administración): 192.168.20.128/25 — Rango de host: 192.168.20.129 a 192.168.20.254 — Broadcast: 192.168.20.255\u003c/li\u003e\n              \u003c/ul\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003eResuelva los siguientes 5 ejercicios de forma individual, mostrando el procedimiento completo. Use como base la red \u003cstrong\u003e192.168.20.0/24\u003c/strong\u003e.\u003c/p\u003e\n              \u003carticle class=\"notes-card\"\u003e\n                \u003csection class=\"r11-exercise\"\u003e\u003cheader class=\"r11-exercise__head\"\u003e\u003cspan class=\"r11-exercise__n\"\u003eEj. 1\u003c/span\u003e\u003ch4\u003eCalcular la nueva máscara\u003c/h4\u003e\u003c/header\u003e\u003cp class=\"r11-exercise__q\"\u003eSi necesita dividir la red 192.168.20.0/24 en 2 subredes iguales, ¿cuántos bits debe prestar y cuál es la nueva máscara en notación decimal y en notación CIDR (/n)?\u003c/p\u003e\n                \u003cdiv class=\"r11-grid\"\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eBits prestados\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input\" data-store=\"g11c_331_e1_bits\" data-track aria-label=\"Bits prestados\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eNueva máscara (decimal)\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e1_mascara\" data-track placeholder=\"0.0.0.0\" aria-label=\"Nueva máscara (decimal)\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eNueva máscara (CIDR /n)\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input\" data-store=\"g11c_331_e1_cidr\" data-track aria-label=\"Nueva máscara (CIDR /n)\"\u003e\u003c/label\u003e\u003c/div\u003e\n                \u003clabel\u003e\u003cspan\u003eProcedimiento\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_331_e1_proc\" data-track placeholder=\"Muestre el procedimiento paso a paso\"\u003e\u003c/textarea\u003e\u003c/label\u003e\u003c/section\u003e\n                \u003csection class=\"r11-exercise\"\u003e\u003cheader class=\"r11-exercise__head\"\u003e\u003cspan class=\"r11-exercise__n\"\u003eEj. 2\u003c/span\u003e\u003ch4\u003eSubred 1 (Ventas)\u003c/h4\u003e\u003c/header\u003e\u003cp class=\"r11-exercise__q\"\u003eDetermine para la Subred 1: dirección de red, primera IP utilizable, última IP utilizable y dirección de broadcast.\u003c/p\u003e\n                \u003cdiv class=\"r11-grid\"\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eDirección de red\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e2_red\" data-track placeholder=\"0.0.0.0\" aria-label=\"Dirección de red\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003ePrimera IP utilizable\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e2_primera\" data-track placeholder=\"0.0.0.0\" aria-label=\"Primera IP utilizable\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eÚltima IP utilizable\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e2_ultima\" data-track placeholder=\"0.0.0.0\" aria-label=\"Última IP utilizable\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eDirección de broadcast\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e2_broadcast\" data-track placeholder=\"0.0.0.0\" aria-label=\"Dirección de broadcast\"\u003e\u003c/label\u003e\u003c/div\u003e\n                \u003clabel\u003e\u003cspan\u003eProcedimiento\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_331_e2_proc\" data-track placeholder=\"Muestre el procedimiento paso a paso\"\u003e\u003c/textarea\u003e\u003c/label\u003e\u003c/section\u003e\n                \u003csection class=\"r11-exercise\"\u003e\u003cheader class=\"r11-exercise__head\"\u003e\u003cspan class=\"r11-exercise__n\"\u003eEj. 3\u003c/span\u003e\u003ch4\u003eSubred 2 (Administración)\u003c/h4\u003e\u003c/header\u003e\u003cp class=\"r11-exercise__q\"\u003eDetermine para la Subred 2: dirección de red, primera IP utilizable, última IP utilizable y dirección de broadcast.\u003c/p\u003e\n                \u003cdiv class=\"r11-grid\"\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eDirección de red\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e3_red\" data-track placeholder=\"0.0.0.0\" aria-label=\"Dirección de red\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003ePrimera IP utilizable\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e3_primera\" data-track placeholder=\"0.0.0.0\" aria-label=\"Primera IP utilizable\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eÚltima IP utilizable\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e3_ultima\" data-track placeholder=\"0.0.0.0\" aria-label=\"Última IP utilizable\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eDirección de broadcast\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e3_broadcast\" data-track placeholder=\"0.0.0.0\" aria-label=\"Dirección de broadcast\"\u003e\u003c/label\u003e\u003c/div\u003e\n                \u003clabel\u003e\u003cspan\u003eProcedimiento\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_331_e3_proc\" data-track placeholder=\"Muestre el procedimiento paso a paso\"\u003e\u003c/textarea\u003e\u003c/label\u003e\u003c/section\u003e\n                \u003csection class=\"r11-exercise\"\u003e\u003cheader class=\"r11-exercise__head\"\u003e\u003cspan class=\"r11-exercise__n\"\u003eEj. 4\u003c/span\u003e\u003ch4\u003eAsignación de IPs\u003c/h4\u003e\u003c/header\u003e\u003cp class=\"r11-exercise__q\"\u003eAsigne una dirección IP válida de cada subred a los siguientes equipos, dejando la primera IP de cada subred para el gateway (router). Ventas: PC_Caja, PC_Venta1, PC_Venta2. Administración: PC_Gerencia, PC_Contable, PC_Bodega.\u003c/p\u003e\u003cdiv class=\"r11-subnets\"\u003e\u003cdiv class=\"r11-subnet\"\u003e\u003cdiv class=\"r11-subnet__head\"\u003e\u003cstrong\u003eSubred Ventas\u003c/strong\u003e\u003cspan class=\"r11-chip\"\u003eSubred 1\u003c/span\u003e\u003c/div\u003e\u003ctable class=\"r11-device-table\"\u003e\u003cthead\u003e\u003ctr\u003e\u003cth\u003eDispositivo\u003c/th\u003e\u003cth\u003eDirección IP asignada\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\u003ctbody\u003e\u003ctr\u003e\u003cth scope=\"row\"\u003eGateway (router)\u003c/th\u003e\u003ctd data-label=\"Dirección IP asignada\"\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e4_gw_ventas\" data-track placeholder=\"0.0.0.0\" aria-label=\"Subred Ventas: Gateway (router)\"\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003cth scope=\"row\"\u003ePC_Caja\u003c/th\u003e\u003ctd data-label=\"Dirección IP asignada\"\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e4_caja\" data-track placeholder=\"0.0.0.0\" aria-label=\"Subred Ventas: PC_Caja\"\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003cth scope=\"row\"\u003ePC_Venta1\u003c/th\u003e\u003ctd data-label=\"Dirección IP asignada\"\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e4_venta1\" data-track placeholder=\"0.0.0.0\" aria-label=\"Subred Ventas: PC_Venta1\"\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003cth scope=\"row\"\u003ePC_Venta2\u003c/th\u003e\u003ctd data-label=\"Dirección IP asignada\"\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e4_venta2\" data-track placeholder=\"0.0.0.0\" aria-label=\"Subred Ventas: PC_Venta2\"\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/tbody\u003e\u003c/table\u003e\u003c/div\u003e\u003cdiv class=\"r11-subnet\"\u003e\u003cdiv class=\"r11-subnet__head\"\u003e\u003cstrong\u003eSubred Administración\u003c/strong\u003e\u003cspan class=\"r11-chip\"\u003eSubred 2\u003c/span\u003e\u003c/div\u003e\u003ctable class=\"r11-device-table\"\u003e\u003cthead\u003e\u003ctr\u003e\u003cth\u003eDispositivo\u003c/th\u003e\u003cth\u003eDirección IP asignada\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\u003ctbody\u003e\u003ctr\u003e\u003cth scope=\"row\"\u003eGateway (router)\u003c/th\u003e\u003ctd data-label=\"Dirección IP asignada\"\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e4_gw_admin\" data-track placeholder=\"0.0.0.0\" aria-label=\"Subred Administración: Gateway (router)\"\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003cth scope=\"row\"\u003ePC_Gerencia\u003c/th\u003e\u003ctd data-label=\"Dirección IP asignada\"\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e4_gerencia\" data-track placeholder=\"0.0.0.0\" aria-label=\"Subred Administración: PC_Gerencia\"\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003cth scope=\"row\"\u003ePC_Contable\u003c/th\u003e\u003ctd data-label=\"Dirección IP asignada\"\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e4_contable\" data-track placeholder=\"0.0.0.0\" aria-label=\"Subred Administración: PC_Contable\"\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003cth scope=\"row\"\u003ePC_Bodega\u003c/th\u003e\u003ctd data-label=\"Dirección IP asignada\"\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e4_bodega\" data-track placeholder=\"0.0.0.0\" aria-label=\"Subred Administración: PC_Bodega\"\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/tbody\u003e\u003c/table\u003e\u003c/div\u003e\u003c/div\u003e\u003c/section\u003e\n                \u003csection class=\"r11-exercise\"\u003e\u003cheader class=\"r11-exercise__head\"\u003e\u003cspan class=\"r11-exercise__n\"\u003eEj. 5\u003c/span\u003e\u003ch4\u003eVerificación en su equipo\u003c/h4\u003e\u003c/header\u003e\u003cp class=\"r11-exercise__q\"\u003eEjecute \u003ccode\u003eipconfig /all\u003c/code\u003e en su computador, capture el resultado e indique en qué red y con qué máscara está configurado su equipo actualmente. Incluya la captura en el PDF que entrega.\u003c/p\u003e\n                \u003cdiv class=\"r11-grid\"\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eDirección IP de su equipo\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e5_ip\" data-track placeholder=\"0.0.0.0\" aria-label=\"Dirección IP de su equipo\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eMáscara\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e5_mascara\" data-track placeholder=\"0.0.0.0\" aria-label=\"Máscara\"\u003e\u003c/label\u003e\u003clabel class=\"r11-field\"\u003e\u003cspan class=\"r11-field__label\"\u003eRed a la que pertenece (dirección de red calculada)\u003c/span\u003e\u003cinput type=\"text\" class=\"r11-input r11-input--ip\" inputmode=\"decimal\" autocomplete=\"off\" spellcheck=\"false\" data-store=\"g11c_331_e5_red\" data-track placeholder=\"0.0.0.0\" aria-label=\"Red a la que pertenece (dirección de red calculada)\"\u003e\u003c/label\u003e\u003c/div\u003e\u003c/section\u003e\n                \u003cdiv id=\"c11Taller331DeadlineControls\" class=\"u-mt-16\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group r11-actions\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarc11Taller331\" class=\"btn-save-response\" onclick=\"actStd_save_c11Taller331()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_c11Taller331()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusc11Taller331\" class=\"activity-saved-notice u-saved\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n                \u003csection class=\"r11-evidence\" aria-label=\"Entrega de evidencia 3.3.1\" data-r11-formats=\".pdf,.doc,.docx\"\u003e\n                \u003cdiv class=\"r11-evidence__head\"\u003e\u003cspan class=\"r11-evidence__icon\" aria-hidden=\"true\"\u003e\u0026#128230;\u003c/span\u003e\n                  \u003cdiv\u003e\u003cstrong\u003eEntrega de evidencia\u003c/strong\u003e\u003cspan class=\"r11-evidence__title\"\u003eTaller de subneteo - Ejercicios 1 a 5 (PDF)\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n                \u003cdl class=\"r11-evidence__facts\"\u003e\n                  \u003cdiv\u003e\u003cdt\u003eArchivo\u003c/dt\u003e\u003cdd\u003e\u003ccode\u003eTaller_Subneteo_NombreAprendiz_FICHA.pdf\u003c/code\u003e\u003c/dd\u003e\u003c/div\u003e\n                  \u003cdiv\u003e\u003cdt\u003eFormatos admitidos\u003c/dt\u003e\u003cdd\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.pdf\u003c/span\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.doc\u003c/span\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.docx\u003c/span\u003e\u003c/dd\u003e\u003c/div\u003e\n                \u003c/dl\u003e\n                \u003cp class=\"r11-evidence__help\"\u003eUse \u003cstrong\u003eEntregar por formulario seguro\u003c/strong\u003e: el portal muestra el estado de subida, confirma la entrega con fecha y hora, y si falla le indica el error y le permite reintentar.\u003c/p\u003e\n                \u003cdiv data-act-std-delivery=\"c11Taller331\"\u003e\u003c/div\u003e\n              \u003c/section\u003e\n                \u003cdiv id=\"c11Taller331GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"transferencia\" class=\"section-title\"\u003e3.4 Actividades de transferencia del conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 Configuración y comprobación de las dos subredes de la papelería en Cisco Packet Tracer.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-orange\"\u003e\u0026#128640;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eLaboratorio — Dos subredes conectadas por router\u003c/h3\u003e\u003cp\u003eDiseño · direccionamiento · pruebas de conectividad\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \n          \u003cdiv class=\"activity open mission-card r11-activity\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eLaboratorio: dos subredes con verificación de conectividad\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cdiv class=\"r11-meta\"\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003ePropósito\u003c/span\u003e\u003cspan\u003eConfigurar y comprobar dos subredes en Cisco Packet Tracer.\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"r11-meta__item\"\u003e\u003cspan class=\"r11-meta__k\"\u003eProducto esperado\u003c/span\u003e\u003cspan\u003eLab_Subredes_Carmen_NombreAprendiz_FICHA.pkt + capturas + análisis.\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003ePropósito:\u003c/strong\u003e aplicar de manera integral el direccionamiento por subredes y las herramientas de validación, configurando y comprobando la conectividad de una red en Cisco Packet Tracer. Recuerde: el objetivo principal no es solo construir la topología, sino \u003cstrong\u003ecomprobar y documentar que la conectividad funciona\u003c/strong\u003e.\u003c/p\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#128421; Escenario\u003c/div\u003e\u003cp\u003eLa papelería de la señora Carmen necesita 2 subredes independientes: \u003cstrong\u003eVentas\u003c/strong\u003e (caja y 2 puntos de atención) y \u003cstrong\u003eAdministración\u003c/strong\u003e (gerencia, contabilidad y bodega), conectadas entre sí a través de un router para que Carmen pueda supervisar ambas desde su oficina.\u003c/p\u003e\u003c/div\u003e\n              \u003ch4\u003ePaso 1 — Diseño de la red\u003c/h4\u003e\n              \u003col\u003e\n                \u003cli\u003eAbra Cisco Packet Tracer y cree un nuevo proyecto.\u003c/li\u003e\n                \u003cli\u003eAgregue 1 Router (genérico) y 2 Switch 2960: uno para la subred Ventas y otro para la subred Administración.\u003c/li\u003e\n                \u003cli\u003eAgregue 3 PCs para Ventas: PC_Caja, PC_Venta1, PC_Venta2, y conéctelos al Switch de Ventas.\u003c/li\u003e\n                \u003cli\u003eAgregue 3 PCs para Administración: PC_Gerencia, PC_Contable, PC_Bodega, y conéctelos al Switch de Administración.\u003c/li\u003e\n                \u003cli\u003eConecte cada Switch a una interfaz distinta del Router (GigabitEthernet0/0 con Ventas, GigabitEthernet0/1 con Administración) con cable recto (Copper Straight-Through).\u003c/li\u003e\n              \u003c/ol\u003e\n              \u003ch4\u003ePaso 2 — Configuración del direccionamiento IP\u003c/h4\u003e\n              \u003cp class=\"intro-text\"\u003eAsigne las direcciones calculadas en el taller de subneteo (Ejercicios 2 a 4) a cada dispositivo:\u003c/p\u003e\n              \u003cdiv class=\"table-scroll\"\u003e\u003ctable class=\"data-table\"\u003e\u003cthead\u003e\u003ctr\u003e\u003cth\u003eDispositivo\u003c/th\u003e\u003cth\u003eDirección IP\u003c/th\u003e\u003cth\u003eMáscara\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\u003ctbody\u003e\u003ctr\u003e\u003ctd\u003eRouter — Gi0/0 (Ventas)\u003c/td\u003e\u003ctd\u003e192.168.20.1\u003c/td\u003e\u003ctd\u003e255.255.255.128\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003eRouter — Gi0/1 (Administración)\u003c/td\u003e\u003ctd\u003e192.168.20.129\u003c/td\u003e\u003ctd\u003e255.255.255.128\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePC_Caja (gateway 192.168.20.1)\u003c/td\u003e\u003ctd\u003e192.168.20.2\u003c/td\u003e\u003ctd\u003e255.255.255.128\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePC_Venta1 (gateway 192.168.20.1)\u003c/td\u003e\u003ctd\u003e192.168.20.3\u003c/td\u003e\u003ctd\u003e255.255.255.128\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePC_Venta2 (gateway 192.168.20.1)\u003c/td\u003e\u003ctd\u003e192.168.20.4\u003c/td\u003e\u003ctd\u003e255.255.255.128\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePC_Gerencia (gateway 192.168.20.129)\u003c/td\u003e\u003ctd\u003e192.168.20.130\u003c/td\u003e\u003ctd\u003e255.255.255.128\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePC_Contable (gateway 192.168.20.129)\u003c/td\u003e\u003ctd\u003e192.168.20.131\u003c/td\u003e\u003ctd\u003e255.255.255.128\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003ePC_Bodega (gateway 192.168.20.129)\u003c/td\u003e\u003ctd\u003e192.168.20.132\u003c/td\u003e\u003ctd\u003e255.255.255.128\u003c/td\u003e\u003c/tr\u003e\u003c/tbody\u003e\u003c/table\u003e\u003c/div\u003e\n              \u003ch4\u003ePaso 3 — Pruebas de conectividad\u003c/h4\u003e\n              \u003col\u003e\n                \u003cli\u003eDesde PC_Caja ejecute \u003ccode\u003eping\u003c/code\u003e a PC_Venta1 (misma subred) y capture el resultado.\u003c/li\u003e\n                \u003cli\u003eDesde PC_Caja ejecute \u003ccode\u003eping\u003c/code\u003e a PC_Gerencia (subred distinta, a través del router) y capture el resultado.\u003c/li\u003e\n                \u003cli\u003eDesde PC_Caja ejecute \u003ccode\u003etracert\u003c/code\u003e a PC_Gerencia y verifique que el paquete pasa por el router (1 salto).\u003c/li\u003e\n                \u003cli\u003eEn cada PC ejecute \u003ccode\u003eipconfig\u003c/code\u003e y confirme que la dirección IP, la máscara y el gateway coinciden con la tabla de asignación.\u003c/li\u003e\n              \u003c/ol\u003e\n              \u003carticle class=\"notes-card\"\u003e\n                \u003cdiv class=\"r11-grid r11-grid--2\"\u003e\n                \u003clabel\u003e\u003cspan\u003e1. Resultado del ping PC_Caja → PC_Venta1 (misma subred)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_341_ping_misma\" data-track placeholder=\"Copie la salida o describa: respuestas, pérdida de paquetes, tiempos\"\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e2. Resultado del ping PC_Caja → PC_Gerencia (otra subred, a través del router)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_341_ping_otra\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e3. Resultado del tracert PC_Caja → PC_Gerencia (¿por qué saltos pasó?)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g11c_341_tracert\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003clabel\u003e\u003cspan\u003e4. Verificación con ipconfig en cada PC (IP, máscara y gateway contra la tabla)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g11c_341_ipconfig\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003c/div\u003e\n                \u003clabel\u003e\u003cspan\u003eAnálisis breve: ¿qué demuestran las pruebas sobre la conectividad de las dos subredes?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g11c_341_analisis\" data-track\u003e\u003c/textarea\u003e\u003c/label\u003e\n                \u003cdiv id=\"c11Lab341DeadlineControls\" class=\"u-mt-16\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group r11-actions\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarc11Lab341\" class=\"btn-save-response\" onclick=\"actStd_save_c11Lab341()\"\u003e\u0026#128190; Guardar respuestas\u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_c11Lab341()\"\u003e\u0026#128196; Exportar a Word\u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusc11Lab341\" class=\"activity-saved-notice u-saved\"\u003e\u0026#9989; Respuestas guardadas correctamente.\u003c/div\u003e\n                \u003csection class=\"r11-evidence\" aria-label=\"Entrega de evidencia 3.4.1\" data-r11-formats=\".pkt,.pdf,.zip\"\u003e\n                \u003cdiv class=\"r11-evidence__head\"\u003e\u003cspan class=\"r11-evidence__icon\" aria-hidden=\"true\"\u003e\u0026#128230;\u003c/span\u003e\n                  \u003cdiv\u003e\u003cstrong\u003eEntrega de evidencia\u003c/strong\u003e\u003cspan class=\"r11-evidence__title\"\u003eLaboratorio dos subredes - papeleria Carmen (.pkt + capturas + analisis)\u003c/span\u003e\u003c/div\u003e\u003c/div\u003e\n                \u003cdl class=\"r11-evidence__facts\"\u003e\n                  \u003cdiv\u003e\u003cdt\u003eArchivo\u003c/dt\u003e\u003cdd\u003e\u003ccode\u003eLab_Subredes_Carmen_NombreAprendiz_FICHA.pkt\u003c/code\u003e\u003c/dd\u003e\u003c/div\u003e\n                  \u003cdiv\u003e\u003cdt\u003eFormatos admitidos\u003c/dt\u003e\u003cdd\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.pkt\u003c/span\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.pdf\u003c/span\u003e\u003cspan class=\"r11-chip r11-chip--format\"\u003e.zip\u003c/span\u003e\u003c/dd\u003e\u003c/div\u003e\n                \u003c/dl\u003e\n                \u003cp class=\"r11-evidence__help\"\u003eUse \u003cstrong\u003eEntregar por formulario seguro\u003c/strong\u003e: el portal muestra el estado de subida, confirma la entrega con fecha y hora, y si falla le indica el error y le permite reintentar.\u003c/p\u003e\n                \u003cdiv data-act-std-delivery=\"c11Lab341\"\u003e\u003c/div\u003e\n              \u003c/section\u003e\n                \u003cdiv id=\"c11Lab341GradeMount\" class=\"u-mt-12\"\u003e\u003c/div\u003e\n              \u003c/article\u003e\n\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"evidencias\" class=\"section-title\"\u003eEvidencias de aprendizaje\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 Lista de chequeo final: lo que se entrega y cómo se evalúa (fase Análisis).\u003c/p\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-blue\"\u003e\u0026#128202;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003ePlanteamiento de evidencias para la evaluación\u003c/h3\u003e\u003cp\u003eActividad · evidencia · criterio · instrumento\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\u003ctable class=\"data-table\"\u003e\u003cthead\u003e\u003ctr\u003e\u003cth\u003eActividad de aprendizaje\u003c/th\u003e\u003cth\u003eEvidencia\u003c/th\u003e\u003cth\u003eCriterio de evaluación\u003c/th\u003e\u003cth\u003eTécnica e instrumento\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\u003ctbody\u003e\u003ctr\u003e\u003ctd\u003e3.1 Reflexión individual escrita + socialización (Paso 1 y 2)\u003c/td\u003e\u003ctd\u003eProducto: respuestas en cuaderno o documento digital. Desempeño: participación en socialización (2–3 min).\u003c/td\u003e\u003ctd\u003eCaracteriza pruebas de fallas en la red según requerimientos técnicos.\u003c/td\u003e\u003ctd\u003eObservación y revisión. Lista de cotejo (participación y respuestas).\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e3.2 Exploración visual Bloques A–D + mapa mental integrador\u003c/td\u003e\u003ctd\u003eExploracion_Contextual_NombreAprendiz_FICHA.pdf + MapaMental_Redes_NombreAprendiz_FICHA.pdf\u003c/td\u003e\u003ctd\u003eCaracteriza pruebas de fallas en la red según requerimientos técnicos. Identifica servicios y protocolos de infraestructura (DHCP, DNS, PROXY).\u003c/td\u003e\u003ctd\u003eEvaluación de producto. Lista de chequeo (IE-01).\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e3.3 Taller de subneteo (Ejercicios 1–5) de la red 192.168.20.0/24\u003c/td\u003e\u003ctd\u003eTaller_Subneteo_NombreAprendiz_FICHA.pdf\u003c/td\u003e\u003ctd\u003eEfectúa pruebas de conectividad de hardware y/o software, operación de servicios y protocolos de infraestructura, disponibilidad, rendimiento y calidad, de acuerdo con normativa de telecomunicaciones, orden de trabajo, aplicando normas de SST y ambientales.\u003c/td\u003e\u003ctd\u003ePrueba escrita/ejercicios. Lista de chequeo (IE-02).\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e3.4 Laboratorio Packet Tracer: 2 subredes + pruebas (ping, tracert, ipconfig)\u003c/td\u003e\u003ctd\u003eLab_Subredes_Carmen_NombreAprendiz_FICHA.pkt + capturas de pruebas + análisis breve\u003c/td\u003e\u003ctd\u003eValida el estado de la red de acuerdo con la conectividad, el inventario tecnológico y su disponibilidad técnica según normativa.\u003c/td\u003e\u003ctd\u003eObservación y revisión de producto. Lista de chequeo (IE-03).\u003c/td\u003e\u003c/tr\u003e\u003c/tbody\u003e\u003c/table\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"version-anterior\" class=\"section-title\"\u003eRegistros de la versión anterior de esta guía\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-teal\"\u003e\u0026#128451;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eRespuestas y entregas conservadas\u003c/h3\u003e\u003cp\u003eSolo consulta: nada se borró\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003eEsta guía se corrigió para que coincida con la guía oficial de grado 11. Si usted\n          ya había trabajado en la versión anterior, sus respuestas y entregas siguen guardadas y se muestran aquí\n          (solo lectura). Su instructor las revisará manualmente.\u003c/p\u003e\n          \u003cdiv data-redes11-legacy\u003e\u003cp class=\"intro-text\"\u003eNo hay registros de la versión anterior.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario de términos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-purple\"\u003e\u0026#128214;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eGlosario\u003c/h3\u003e\u003cp\u003eTérminos clave de la guía\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdl class=\"glossary\"\u003e\u003cdt\u003eSubred (Subnet)\u003c/dt\u003e\u003cdd\u003ePorción de una red IP resultante de dividir un espacio de direccionamiento mayor mediante el préstamo de bits de host, delimitada por su propia dirección de red y de broadcast.\u003c/dd\u003e\u003cdt\u003eSubneteo (Subnetting)\u003c/dt\u003e\u003cdd\u003eTécnica de dividir una red IP en subredes más pequeñas ampliando la máscara de subred, con el fin de organizar, aislar y controlar el tráfico.\u003c/dd\u003e\u003cdt\u003eFLSM (Fixed Length Subnet Mask)\u003c/dt\u003e\u003cdd\u003eMétodo de subneteo en el que todas las subredes resultantes tienen el mismo tamaño (misma máscara).\u003c/dd\u003e\u003cdt\u003eVLSM (Variable Length Subnet Mask)\u003c/dt\u003e\u003cdd\u003eMétodo de subneteo que permite subredes de distinto tamaño según la cantidad de hosts requerida en cada una.\u003c/dd\u003e\u003cdt\u003eCIDR\u003c/dt\u003e\u003cdd\u003eNotación que expresa la máscara de subred como el número de bits en 1 (ej. /25).\u003c/dd\u003e\u003cdt\u003eDirección de red\u003c/dt\u003e\u003cdd\u003ePrimera dirección IP de una subred, usada para identificarla; no es asignable a un host.\u003c/dd\u003e\u003cdt\u003eDirección de broadcast\u003c/dt\u003e\u003cdd\u003eÚltima dirección IP de una subred, usada para enviar tráfico a todos los hosts de esa subred; no es asignable a un host.\u003c/dd\u003e\u003cdt\u003eRango de host\u003c/dt\u003e\u003cdd\u003eConjunto de direcciones IP asignables a equipos dentro de una subred, ubicado entre la dirección de red y la de broadcast.\u003c/dd\u003e\u003cdt\u003eLAN (Local Area Network)\u003c/dt\u003e\u003cdd\u003eRed de área local que interconecta dispositivos en un espacio limitado (hogar, oficina, sede).\u003c/dd\u003e\u003cdt\u003eWAN (Wide Area Network)\u003c/dt\u003e\u003cdd\u003eRed que interconecta LANs distantes geográficamente, típicamente a través de un proveedor de servicios de telecomunicaciones.\u003c/dd\u003e\u003cdt\u003eDHCP\u003c/dt\u003e\u003cdd\u003eProtocolo que asigna automáticamente parámetros de red (IP, máscara, gateway, DNS) a los equipos cliente.\u003c/dd\u003e\u003cdt\u003eDNS (Domain Name System)\u003c/dt\u003e\u003cdd\u003eSistema distribuido que traduce nombres de dominio a direcciones IP.\u003c/dd\u003e\u003cdt\u003eProxy\u003c/dt\u003e\u003cdd\u003eServidor intermediario que gestiona solicitudes entre clientes y otros servidores, aplicando control, filtrado o caché.\u003c/dd\u003e\u003cdt\u003eICMP\u003c/dt\u003e\u003cdd\u003eProtocolo de control usado para mensajes de diagnóstico y error; herramientas como ping se basan en ICMP.\u003c/dd\u003e\u003cdt\u003ePing\u003c/dt\u003e\u003cdd\u003eHerramienta de diagnóstico que verifica conectividad enviando mensajes ICMP Echo.\u003c/dd\u003e\u003cdt\u003eTracert / traceroute\u003c/dt\u003e\u003cdd\u003eHerramienta que muestra la ruta (saltos) que siguen los paquetes hasta un destino.\u003c/dd\u003e\u003cdt\u003eNslookup\u003c/dt\u003e\u003cdd\u003eHerramienta que consulta servidores DNS para verificar la resolución de nombres.\u003c/dd\u003e\u003cdt\u003eIpconfig\u003c/dt\u003e\u003cdd\u003eComando que muestra la configuración IP vigente de un equipo (dirección, máscara, gateway).\u003c/dd\u003e\u003cdt\u003eGateway (puerta de enlace predeterminada)\u003c/dt\u003e\u003cdd\u003eDirección del router por donde un equipo envía tráfico destinado a otras redes (fuera de su subred).\u003c/dd\u003e\u003cdt\u003eCaptura de pantalla\u003c/dt\u003e\u003cdd\u003eImagen de lo que se ve en la pantalla; en Windows se toma con las teclas Windows + Shift + S.\u003c/dd\u003e\u003cdt\u003ePacket Tracer\u003c/dt\u003e\u003cdd\u003eSimulador de redes de Cisco para diseñar, configurar y probar redes en el computador, sin usar equipos reales.\u003c/dd\u003e\u003c/dl\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n      \u003cdiv id=\"referencias\" class=\"section-title\"\u003eReferentes bibliográficos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-teal\"\u003e\u0026#128279;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eReferencias (IEEE)\u003c/h3\u003e\u003cp\u003eFuentes de la guía oficial\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003col class=\"references\"\u003e\u003cli\u003eCisco Networking Academy, «Networking Basics», Cisco Skills for All. \u003ca href=\"https://skillsforall.com/course/networking-basics\" target=\"_blank\" rel=\"noopener\"\u003eskillsforall.com\u003c/a\u003e\u003c/li\u003e\u003cli\u003eCisco Networking Academy, «Packet Tracer», NetAcad. \u003ca href=\"https://www.netacad.com/courses/packet-tracer\" target=\"_blank\" rel=\"noopener\"\u003enetacad.com\u003c/a\u003e\u003c/li\u003e\u003cli\u003eJ. Postel, «Internet Protocol», RFC 791, sep. 1981.\u003c/li\u003e\u003cli\u003eJ. C. Mogul y J. Postel, «Internet Standard Subnetting Procedure», RFC 950, ago. 1985. \u003ca href=\"https://www.rfc-editor.org/rfc/rfc950\" target=\"_blank\" rel=\"noopener\"\u003erfc-editor.org\u003c/a\u003e\u003c/li\u003e\u003cli\u003eT. Pummill y B. Manning, «Variable Length Subnet Table For IPv4», RFC 1878, dic. 1995.\u003c/li\u003e\u003cli\u003eR. Droms, «Dynamic Host Configuration Protocol», RFC 2131, mar. 1997.\u003c/li\u003e\u003cli\u003eP. Mockapetris, «Domain names—Concepts and facilities», RFC 1034, nov. 1987.\u003c/li\u003e\u003cli\u003eJ. Postel, «Internet Control Message Protocol», RFC 792, sep. 1981.\u003c/li\u003e\u003cli\u003eMicrosoft, «ipconfig», «ping», «tracert», «nslookup», Microsoft Learn (Windows Commands). \u003ca href=\"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig\" target=\"_blank\" rel=\"noopener\"\u003elearn.microsoft.com\u003c/a\u003e\u003c/li\u003e\u003cli\u003eIEEE, «IEEE Standard for Ethernet (IEEE Std 802.3)», IEEE, 2022.\u003c/li\u003e\u003cli\u003eTelecommunications Industry Association, «ANSI/TIA-568.2-D: Balanced Twisted-Pair Telecommunications Cabling and Components Standard», TIA, 2018.\u003c/li\u003e\u003c/ol\u003e\n          \u003cp class=\"intro-text\"\u003eControl de cambios: Dubier Orlando Millán Barbosa (Instructor Técnico, CIAS — Regional Boyacá), 13/08/2026 — Actualización.\u003c/p\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n";
